CREATE TABLE perf22_query_runs (run_id INTEGER PRIMARY KEY, query_version TEXT NOT NULL, elapsed_ms REAL NOT NULL);
INSERT INTO perf22_query_runs VALUES (1, 'v1', 2.4), (2, 'v1', 2.1), (3, 'v2', 1.8), (4, 'v2', 1.9);
SELECT query_version, ROUND(AVG(elapsed_ms), 2) AS average_ms FROM perf22_query_runs GROUP BY query_version ORDER BY query_version;

